{-| @Backend.Runtime.Host.Tls — secured connections behind their tokens, as `Pudu.Eval.Tls` answers them, through the system's TLS library. Verification is always on, trust is the system's store, and the name proven is the name the caller gave. -}
module Pudu.Backend.Runtime.Host.Tls (hostTlsParts, tlsLibraryMarker) where

import Data.Text (Text)

{-| The line whose presence in a program's C says the program links the
    system's TLS library. -}
tlsLibraryMarker :: Text
tlsLibraryMarker = "#include <openssl/ssl.h>"

{-| Each part: its name, the parts it needs, and its lines. -}
hostTlsParts :: [(Text, [Text], [Text])]
hostTlsParts =
  [ ("host_tls", ["host_sockets", "host_optional", "host_done", "host_fail", "host_fail_io", "host_grow", "host_gate", "host_path", "kernel_signed", "kernel_int", "text_retain"],
      [ tlsLibraryMarker
      , "#include <openssl/err.h>"
      , "/* One secured connection: the session, the descriptor beneath it, the"
      , "   name it was opened against, and whether its ending has been read. An"
      , "   empty slot has no session. */"
      , "typedef struct { SSL *session; int descriptor, ended; pudu_text host; } pudu_host_secured;"
      , "PUDU_OPTIONAL static pudu_host_secured *pudu_host_tls_table = NULL;"
      , "PUDU_OPTIONAL static size_t pudu_host_tls_room = 0, pudu_host_tls_held = 0;"
      , "PUDU_OPTIONAL static int64_t pudu_host_tls_next = 1;"
      , "PUDU_OPTIONAL static SSL_CTX *pudu_host_tls_trust = NULL;"
      , "PUDU_OPTIONAL static inline pudu_host_secured *pudu_host_tls_find(pudu_int token) {"
      , "  int64_t wanted = pudu_kernel_signed(token.bits);"
      , "  if (wanted < 1 || (uint64_t)wanted >= pudu_host_tls_room) return NULL;"
      , "  return pudu_host_tls_table[wanted].session == NULL ? NULL : &pudu_host_tls_table[wanted];"
      , "}"
      , "/* Forgets the token and hands over what it held; the table goes with its"
      , "   last connection. */"
      , "PUDU_OPTIONAL static inline int pudu_host_tls_take(pudu_int token, pudu_host_secured *taken) {"
      , "  pudu_host_secured *found = pudu_host_tls_find(token);"
      , "  if (found == NULL) return 0;"
      , "  *taken = *found;"
      , "  found->session = NULL;"
      , "  pudu_host_tls_held -= 1;"
      , "  if (pudu_host_tls_held == 0) { free(pudu_host_tls_table); pudu_host_tls_table = NULL; pudu_host_tls_room = 0; }"
      , "  return 1;"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_tls_keep(SSL *session, int descriptor, pudu_text host) {"
      , "  int64_t token = pudu_host_tls_next++;"
      , "  if ((size_t)token >= pudu_host_tls_room) {"
      , "    size_t room = pudu_host_tls_room < 8 ? 8 : pudu_host_tls_room * 2;"
      , "    pudu_host_secured *table;"
      , "    while (room <= (size_t)token) room *= 2;"
      , "    table = pudu_host_grow(pudu_host_tls_table, room * sizeof *table);"
      , "    memset(table + pudu_host_tls_room, 0, (room - pudu_host_tls_room) * sizeof *table);"
      , "    pudu_host_tls_table = table;"
      , "    pudu_host_tls_room = room;"
      , "  }"
      , "  pudu_host_tls_table[token].session = session;"
      , "  pudu_host_tls_table[token].descriptor = descriptor;"
      , "  pudu_host_tls_table[token].ended = 0;"
      , "  pudu_host_tls_table[token].host = pudu_text_retain(host);"
      , "  pudu_host_tls_held += 1;"
      , "  return pudu_kernel_int(token);"
      , "}"
      , "/* Releases what a forgotten token held. */"
      , "PUDU_OPTIONAL static inline void pudu_host_tls_drop(pudu_host_secured *taken) {"
      , "  SSL_free(taken->session);"
      , "  (void)close(taken->descriptor);"
      , "  pudu_text_release(taken->host);"
      , "}"
      , "/* The one client configuration of a run: the peer is verified against the"
      , "   system's trust store, and nothing older than TLS 1.2 is spoken. */"
      , "PUDU_OPTIONAL static inline SSL_CTX *pudu_host_tls_context(void) {"
      , "  if (pudu_host_tls_trust == NULL) {"
      , "    SSL_CTX *made = SSL_CTX_new(TLS_client_method());"
      , "    if (made == NULL) return NULL;"
      , "    (void)SSL_CTX_set_min_proto_version(made, TLS1_2_VERSION);"
      , "    SSL_CTX_set_verify(made, SSL_VERIFY_PEER, NULL);"
      , "    (void)SSL_CTX_set_default_verify_paths(made);"
      , "    (void)SSL_CTX_set_mode(made, SSL_MODE_ENABLE_PARTIAL_WRITE | SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER);"
      , "    pudu_host_tls_trust = made;"
      , "  }"
      , "  return pudu_host_tls_trust;"
      , "}"
      , "/* What a step that did not finish needs: 1 try again, 0 the budget is"
      , "   spent, 2 the far end said it has finished, 4 the far end went without"
      , "   saying so, -1 it failed. */"
      , "PUDU_OPTIONAL static inline int pudu_host_tls_step(SSL *session, int descriptor, int result, int64_t budget, int64_t started) {"
      , "  int why = SSL_get_error(session, result);"
      , "  if (why == SSL_ERROR_WANT_READ) return pudu_host_socket_ready(descriptor, POLLIN, budget, started) ? 1 : 0;"
      , "  if (why == SSL_ERROR_WANT_WRITE) return pudu_host_socket_ready(descriptor, POLLOUT, budget, started) ? 1 : 0;"
      , "  if (why == SSL_ERROR_ZERO_RETURN) return 2;"
      , "  if (why == SSL_ERROR_SYSCALL && ERR_peek_error() == 0 && (result == 0 || errno == 0)) return 4;"
      , "#if defined(SSL_R_UNEXPECTED_EOF_WHILE_READING)"
      , "  if (why == SSL_ERROR_SSL && ERR_GET_REASON(ERR_peek_error()) == SSL_R_UNEXPECTED_EOF_WHILE_READING) { ERR_clear_error(); return 4; }"
      , "#endif"
      , "  return -1;"
      , "}"
      , "/* A refusal of the library's own: what was being done and the library's"
      , "   reason, a failed verification's reason first. A failure of the"
      , "   descriptor is worded as a plain endpoint words it. */"
      , "PUDU_OPTIONAL static inline void pudu_host_tls_refuse(const char *what, const char *operation, SSL *session, int code) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  unsigned long queued = ERR_peek_last_error();"
      , "  long verified = session == NULL ? X509_V_OK : SSL_get_verify_result(session);"
      , "  const char *reason = verified != X509_V_OK ? X509_verify_cert_error_string(verified) : queued != 0 ? ERR_reason_error_string(queued) : NULL;"
      , "  char words[320];"
      , "  ERR_clear_error();"
      , "  if (reason == NULL && code != 0) { pudu_host_fail_io(none, operation, code); return; }"
      , "  if (reason == NULL) (void)snprintf(words, sizeof words, \"%s\", what);"
      , "  else (void)snprintf(words, sizeof words, \"%s (%s)\", what, reason);"
      , "  pudu_host_fail(words);"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_tls_timed_out(pudu_int token) {"
      , "  pudu_host_secured taken;"
      , "  if (pudu_host_tls_take(token, &taken)) pudu_host_tls_drop(&taken);"
      , "  pudu_host_fail(\"operation timed out\");"
      , "}"
      ])
  , ("host_tls_secure", ["host_tls"],
      [ "/* Proves the far end of a connected descriptor is the named host, within"
      , "   what is left of a budget. The descriptor is closed when it is not. */"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_tls_secure(int descriptor, pudu_text host, int64_t budget, int64_t started) {"
      , "  SSL_CTX *trust = pudu_host_tls_context();"
      , "  SSL *session = trust == NULL ? NULL : SSL_new(trust);"
      , "  char *name = pudu_host_path(host);"
      , "  unsigned char literal[16];"
      , "  int state = -1, code = 0;"
      , "  int numbered = inet_pton(AF_INET, name, literal) == 1 || inet_pton(AF_INET6, name, literal) == 1;"
      , "  if (session != NULL && SSL_set_fd(session, descriptor) == 1"
      , "      && (numbered ? X509_VERIFY_PARAM_set1_ip_asc(SSL_get0_param(session), name) : X509_VERIFY_PARAM_set1_host(SSL_get0_param(session), name, 0)) == 1) {"
      , "    if (!numbered) (void)SSL_set_tlsext_host_name(session, name);"
      , "    pudu_host_leave();"
      , "    for (;;) {"
      , "      int result;"
      , "      ERR_clear_error();"
      , "      errno = 0;"
      , "      result = SSL_connect(session);"
      , "      if (result == 1) { state = 3; break; }"
      , "      code = errno;"
      , "      state = pudu_host_tls_step(session, descriptor, result, budget, started);"
      , "      if (state != 1) break;"
      , "    }"
      , "    pudu_host_enter();"
      , "  }"
      , "  free(name);"
      , "  if (state == 3) {"
      , "    pudu_host_done(0);"
      , "    return pudu_host_tls_keep(session, descriptor, host);"
      , "  }"
      , "  if (state == 0) pudu_host_fail(\"operation timed out\");"
      , "  else if (state == 2 || state == 4) pudu_host_fail(\"HandshakeFailed Error_EOF\");"
      , "  else pudu_host_tls_refuse(\"HandshakeFailed\", \"Network.Socket.recvBuf\", session, code);"
      , "  if (session != NULL) SSL_free(session);"
      , "  (void)close(descriptor);"
      , "  return pudu_kernel_int(0);"
      , "}"
      ])
  , ("host_tls_connecting", ["host_tls_secure", "host_socket_dialing"],
      [ "/* A secured connection to somewhere else under one budget of milliseconds. */"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_tls_connecting(pudu_text host, pudu_int port, int64_t budget) {"
      , "  int64_t started = pudu_host_socket_clock();"
      , "  int descriptor = pudu_host_socket_dialing(host, port, budget);"
      , "  return descriptor < 0 ? pudu_kernel_int(0) : pudu_host_tls_secure(descriptor, host, budget, started);"
      , "}"
      ])
  , ("host_tls_connect", ["host_tls_connecting"],
      [ "static pudu_int pudu_host_tls_connect(pudu_text host, pudu_int port) { return pudu_host_tls_connecting(host, port, -1); }"
      ])
  , ("host_tls_connect_within", ["host_tls_connecting"],
      [ "static pudu_int pudu_host_tls_connect_within(pudu_text host, pudu_int port, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_tls_connecting(host, port, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_tls_upgrade_within", ["host_tls_secure"],
      [ "/* Secures a plain endpoint the application protocol has agreed to secure."
      , "   The plain token is gone whether or not the far end proves itself. */"
      , "static pudu_int pudu_host_tls_upgrade_within(pudu_int token, pudu_text host, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  int descriptor = pudu_host_socket_take(token);"
      , "  if (descriptor < 0) { pudu_host_fail(\"the plain connection is closed\"); return pudu_kernel_int(0); }"
      , "  if (budget == 0) { (void)close(descriptor); pudu_host_fail(\"operation timed out\"); return pudu_kernel_int(0); }"
      , "  return pudu_host_tls_secure(descriptor, host, budget < 0 ? -1 : budget, pudu_host_socket_clock());"
      , "}"
      ])
  , ("host_tls_sending", ["host_tls"],
      [ "/* Every byte, however many records that takes. The session is held for"
      , "   the wait, so a close from another thread cannot free it underneath. */"
      , "PUDU_OPTIONAL static inline int pudu_host_tls_sending(pudu_int token, pudu_box *chunk, int64_t budget) {"
      , "  pudu_text bytes = chunk->fields[0].text;"
      , "  pudu_host_secured *held = pudu_host_tls_find(token);"
      , "  SSL *session;"
      , "  size_t sent = 0;"
      , "  int descriptor, state = 3, code = 0;"
      , "  if (held == NULL) { pudu_host_fail(\"the secured connection is closed\"); return 0; }"
      , "  session = held->session;"
      , "  descriptor = held->descriptor;"
      , "  if (budget == 0) state = 0;"
      , "  else {"
      , "    int64_t started = pudu_host_socket_clock();"
      , "    (void)SSL_up_ref(session);"
      , "    pudu_host_leave();"
      , "    while (sent < bytes.length) {"
      , "      size_t part = bytes.length - sent > 1048576 ? 1048576 : bytes.length - sent;"
      , "      int wrote;"
      , "      ERR_clear_error();"
      , "      errno = 0;"
      , "      wrote = SSL_write(session, bytes.bytes + sent, (int)part);"
      , "      if (wrote > 0) { sent += (size_t)wrote; continue; }"
      , "      code = errno;"
      , "      state = pudu_host_tls_step(session, descriptor, wrote, budget, started);"
      , "      if (state != 1) break;"
      , "      state = 3;"
      , "    }"
      , "    pudu_host_enter();"
      , "    if (state != 3 && state != 0) pudu_host_tls_refuse(\"Terminated\", \"Network.Socket.sendBuf\", session, state == 2 || state == 4 ? EPIPE : code);"
      , "    SSL_free(session);"
      , "  }"
      , "  if (state == 0) { pudu_host_tls_timed_out(token); return 0; }"
      , "  if (state != 3) return 0;"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_tls_send", ["host_tls_sending"],
      [ "static int pudu_host_tls_send(pudu_int token, pudu_box *chunk) { return pudu_host_tls_sending(token, chunk, -1); }"
      ])
  , ("host_tls_send_within", ["host_tls_sending"],
      [ "static int pudu_host_tls_send_within(pudu_int token, pudu_box *chunk, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_tls_sending(token, chunk, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_tls_receiving", ["host_tls", "kernel_fresh", "bytes_wrap"],
      [ "/* What the next record held; state 2 the first time the far end is"
      , "   found to have finished, and a refusal on every read after that. A"
      , "   count above zero asks for bytes and does not size the answer. */"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_host_tls_receiving(pudu_int token, pudu_int count, int64_t budget) {"
      , "  pudu_host_secured *held;"
      , "  pudu_text chunk;"
      , "  unsigned char *bytes;"
      , "  SSL *session;"
      , "  int descriptor, got = 0, state = 0, code = 0;"
      , "  if (pudu_kernel_signed(count.bits) <= 0) { pudu_host_done(0); return pudu_bytes_wrap(pudu_kernel_fresh(0, &bytes)); }"
      , "  held = pudu_host_tls_find(token);"
      , "  if (held == NULL) { pudu_host_fail(\"the secured connection is closed\"); return NULL; }"
      , "  if (held->ended) { pudu_host_fail(\"PostHandshake Error_EOF\"); return NULL; }"
      , "  session = held->session;"
      , "  descriptor = held->descriptor;"
      , "  chunk = pudu_kernel_fresh(16384, &bytes);"
      , "  if (budget != 0) {"
      , "    int64_t started = pudu_host_socket_clock();"
      , "    (void)SSL_up_ref(session);"
      , "    pudu_host_leave();"
      , "    for (;;) {"
      , "      ERR_clear_error();"
      , "      errno = 0;"
      , "      got = SSL_read(session, bytes, 16384);"
      , "      if (got > 0) { state = 3; break; }"
      , "      code = errno;"
      , "      state = pudu_host_tls_step(session, descriptor, got, budget, started);"
      , "      if (state != 1) break;"
      , "    }"
      , "    pudu_host_enter();"
      , "    if (state == -1) pudu_host_tls_refuse(\"Terminated\", \"Network.Socket.recvBuf\", session, code);"
      , "    SSL_free(session);"
      , "  }"
      , "  if (state != 3) pudu_text_release(chunk);"
      , "  if (state == 0) { pudu_host_tls_timed_out(token); return NULL; }"
      , "  if (state == 2 || state == 4) {"
      , "    held = pudu_host_tls_find(token);"
      , "    if (held != NULL && held->session == session) held->ended = 1;"
      , "    pudu_host_done(2);"
      , "    return NULL;"
      , "  }"
      , "  if (state != 3) return NULL;"
      , "  chunk.length = (size_t)got;"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(chunk);"
      , "}"
      ])
  , ("host_tls_receive", ["host_tls_receiving"],
      [ "static pudu_box *pudu_host_tls_receive(pudu_int token, pudu_int count) { return pudu_host_tls_receiving(token, count, -1); }"
      ])
  , ("host_tls_receive_within", ["host_tls_receiving"],
      [ "static pudu_box *pudu_host_tls_receive_within(pudu_int token, pudu_int count, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_tls_receiving(token, count, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_tls_closing", ["host_tls"],
      [ "/* The protocol's own goodbye, then the descriptor. A far end that has"
      , "   gone already is an ordinary ending; only a spent budget is a refusal,"
      , "   and the connection is closed either way. */"
      , "PUDU_OPTIONAL static inline int pudu_host_tls_closing(pudu_int token, int64_t budget) {"
      , "  pudu_host_secured taken;"
      , "  int spent = budget == 0;"
      , "  if (!pudu_host_tls_take(token, &taken)) { pudu_host_done(0); return 1; }"
      , "  if (!spent) {"
      , "    int64_t started = pudu_host_socket_clock();"
      , "    pudu_host_leave();"
      , "    for (;;) {"
      , "      int result, state;"
      , "      ERR_clear_error();"
      , "      result = SSL_shutdown(taken.session);"
      , "      if (result >= 0) break;"
      , "      state = pudu_host_tls_step(taken.session, taken.descriptor, result, budget, started);"
      , "      if (state == 1) continue;"
      , "      spent = state == 0;"
      , "      break;"
      , "    }"
      , "    pudu_host_enter();"
      , "    ERR_clear_error();"
      , "  }"
      , "  pudu_host_tls_drop(&taken);"
      , "  if (spent) { pudu_host_fail(\"operation timed out\"); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_tls_close", ["host_tls_closing"],
      [ "static int pudu_host_tls_close(pudu_int token) { return pudu_host_tls_closing(token, -1); }"
      ])
  , ("host_tls_close_within", ["host_tls_closing"],
      [ "static int pudu_host_tls_close_within(pudu_int token, pudu_int within) {"
      , "  int64_t budget = pudu_kernel_signed(within.bits);"
      , "  return pudu_host_tls_closing(token, budget < 0 ? -1 : budget);"
      , "}"
      ])
  , ("host_tls_peer", ["host_tls"],
      [ "/* The name the connection was opened against, which is the name proven. */"
      , "static pudu_text pudu_host_tls_peer(pudu_int token) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  pudu_host_secured *held = pudu_host_tls_find(token);"
      , "  if (held == NULL) { pudu_host_fail(\"the secured connection is closed\"); return none; }"
      , "  pudu_host_done(0);"
      , "  return pudu_text_retain(held->host);"
      , "}"
      ])
  ]
